const hostNavigationRoutes: Readonly<Record<string, string>> = {
  "product-a.overview": "/overview",
  "product-a.catalog": "/catalog",
  "product-a.quality-rules": "/quality-rules",
  "product-a.issues": "/issues",
  "product-a.audit": "/audit",
};

export const productAHostActions = [
  { target: "product-a.overview", label: "打开运营总览" },
  { target: "product-a.catalog", label: "打开数据目录" },
  { target: "product-a.quality-rules", label: "打开质量规则" },
  { target: "product-a.issues", label: "打开问题工单" },
  { target: "product-a.audit", label: "打开审计中心" },
] as const;

/** Product A is the final authority for mapping an opaque assistant action to a local route. */
export function resolveProductAHostNavigation(
  value: unknown,
): string | undefined {
  if (typeof value !== "object" || value === null || Array.isArray(value))
    return undefined;
  const candidate = value as Record<string, unknown>;
  if (
    candidate["type"] !== "host.navigate" ||
    typeof candidate["target"] !== "string"
  )
    return undefined;
  return hostNavigationRoutes[candidate["target"]];
}
