import { ProCard, ProList } from "@ant-design/pro-components";
import { Tag, Typography } from "antd";

import { productConfig, type IssueTicket } from "../config.js";

const { Text } = Typography;

const priorityColor: Record<IssueTicket["priority"], string> = {
  P1: "red",
  P2: "orange",
  P3: "blue",
};

const statusColor: Record<IssueTicket["status"], string> = {
  待处理: "warning",
  处理中: "processing",
  已关闭: "success",
};

export function IssuesPage() {
  return (
    <ProCard title="开放工单队列" subTitle="OPEN ISSUES · SLA TRACKING">
      <ProList<IssueTicket>
        rowKey="id"
        dataSource={[...productConfig.issueTickets]}
        metas={{
          title: {
            render: (_, row) => (
              <>
                <Tag color={priorityColor[row.priority]}>{row.priority}</Tag>
                {row.title}
              </>
            ),
          },
          description: {
            render: (_, row) => (
              <Text type="secondary">
                {row.id} · {row.object} · 责任人 {row.assignee}
              </Text>
            ),
          },
          subTitle: {
            render: (_, row) => (
              <>
                <Tag color={statusColor[row.status]}>{row.status}</Tag>
                <Text type="secondary">SLA {row.sla}</Text>
              </>
            ),
          },
          actions: {
            render: (_, row) => <Text type="secondary">更新 {row.updatedAt}</Text>,
          },
        }}
      />
    </ProCard>
  );
}
