import { ProCard, ProTable } from "@ant-design/pro-components";
import type { ProColumns } from "@ant-design/pro-components";
import { Tag } from "antd";

import { productConfig, type AuditRecord } from "../config.js";

const resultColor: Record<AuditRecord["result"], string> = {
  成功: "success",
  拒绝: "error",
  告警: "warning",
};

const columns: ProColumns<AuditRecord>[] = [
  { title: "流水号", dataIndex: "id", width: 110, copyable: true },
  { title: "操作", dataIndex: "action", width: 140 },
  { title: "操作人", dataIndex: "actor", width: 120 },
  { title: "目标对象", dataIndex: "target", ellipsis: true },
  {
    title: "结果",
    dataIndex: "result",
    width: 90,
    render: (_, row) => <Tag color={resultColor[row.result]}>{row.result}</Tag>,
  },
  { title: "来源 IP", dataIndex: "ip", width: 130 },
  { title: "时间", dataIndex: "time", width: 90, search: false },
];

export function AuditPage() {
  return (
    <ProCard title="审计事件流" subTitle="AUDIT TRAIL · LAST 24H">
      <ProTable<AuditRecord>
        rowKey="id"
        columns={columns}
        dataSource={[...productConfig.auditRecords]}
        search={{ labelWidth: "auto" }}
        pagination={false}
        options={false}
        toolBarRender={false}
      />
    </ProCard>
  );
}
