import { ProCard, ProTable } from "@ant-design/pro-components";
import { Progress, Tag } from "antd";
import type { ProColumns } from "@ant-design/pro-components";

import { productConfig, type CatalogEntry } from "../config.js";

const columns: ProColumns<CatalogEntry>[] = [
  { title: "表名", dataIndex: "name", copyable: true, width: 180 },
  { title: "数据域", dataIndex: "domain", width: 120 },
  { title: "分层", dataIndex: "layer", width: 80 },
  { title: "负责人", dataIndex: "owner", width: 90 },
  { title: "记录量", dataIndex: "records", width: 90, search: false },
  {
    title: "质量分",
    dataIndex: "quality",
    width: 140,
    search: false,
    render: (_, row) => (
      <Progress
        percent={row.quality}
        size="small"
        status={row.quality >= 95 ? "success" : row.quality >= 90 ? "normal" : "exception"}
      />
    ),
  },
  { title: "新鲜度", dataIndex: "freshness", width: 110, search: false },
  {
    title: "标签",
    dataIndex: "tags",
    search: false,
    render: (_, row) => row.tags.map((tag) => <Tag key={tag}>{tag}</Tag>),
  },
];

export function CatalogPage() {
  return (
    <ProCard title="纳管对象清单" subTitle="REGISTERED TABLES · EAST CHINA PROD">
      <ProTable<CatalogEntry>
        rowKey="id"
        columns={columns}
        dataSource={[...productConfig.catalog]}
        search={{ labelWidth: "auto" }}
        pagination={{ pageSize: 10, showSizeChanger: false }}
        options={false}
        toolBarRender={false}
      />
    </ProCard>
  );
}
