import { useEffect } from "react";
import { isBrowser } from "../../isBrowser/index.js";
function useDocumentTitle(titleInfo, appDefaultTitle) {
    const titleText = 'string' == typeof titleInfo.title ? titleInfo.title : appDefaultTitle;
    useEffect(()=>{
        if (isBrowser() && titleText) document.title = titleText;
    }, [
        titleInfo.title,
        titleText
    ]);
}
export { useDocumentTitle };
