import { ProCard, ProTable } from "@ant-design/pro-components";
import type { ProColumns } from "@ant-design/pro-components";
import { Badge, Tag } from "antd";

import { productConfig, type QualityRule } from "../config.js";

const severityColor: Record<QualityRule["severity"], string> = {
  高: "red",
  中: "orange",
  低: "blue",
};

const columns: ProColumns<QualityRule>[] = [
  { title: "规则 ID", dataIndex: "id", width: 100, copyable: true },
  { title: "规则名称", dataIndex: "name", width: 160 },
  { title: "质量维度", dataIndex: "dimension", width: 100 },
  { title: "校验对象", dataIndex: "target", ellipsis: true },
  {
    title: "严重级别",
    dataIndex: "severity",
    width: 100,
    render: (_, row) => <Tag color={severityColor[row.severity]}>{row.severity}</Tag>,
  },
  {
    title: "状态",
    dataIndex: "status",
    width: 100,
    render: (_, row) => (
      <Badge
        status={row.status === "启用" ? "success" : row.status === "草稿" ? "default" : "error"}
        text={row.status}
      />
    ),
  },
  {
    title: "通过率",
    dataIndex: "passRate",
    width: 90,
    search: false,
    render: (_, row) => (row.passRate > 0 ? `${row.passRate}%` : "—"),
  },
  { title: "最近执行", dataIndex: "lastRun", width: 100, search: false },
];

export function QualityRulesPage() {
  return (
    <ProCard title="规则执行面板" subTitle="RULE LIBRARY · 1284 ACTIVE">
      <ProTable<QualityRule>
        rowKey="id"
        columns={columns}
        dataSource={[...productConfig.qualityRules]}
        search={{ labelWidth: "auto" }}
        pagination={false}
        options={false}
        toolBarRender={false}
      />
    </ProCard>
  );
}
