export interface DemoEntity {
  readonly id: "orders" | "customers";
  readonly name: string;
  readonly kind: string;
  readonly route: string;
  readonly owner: string;
  readonly records: string;
  readonly quality: number;
  readonly freshness: string;
  readonly status: string;
}

export interface DemoActivity {
  readonly time: string;
  readonly title: string;
  readonly detail: string;
  readonly tone: "good" | "warn" | "neutral";
}

export type NavKey = "overview" | "catalog" | "quality-rules" | "issues" | "audit";

export interface DemoNavItem {
  readonly key: NavKey;
  readonly path: string;
  readonly label: string;
  readonly pageRoute: string;
  readonly pageTitle: string;
  readonly pageType: string;
  readonly module: string;
  readonly description: string;
}

export interface CatalogEntry {
  readonly id: string;
  readonly name: string;
  readonly domain: string;
  readonly layer: string;
  readonly owner: string;
  readonly records: string;
  readonly quality: number;
  readonly freshness: string;
  readonly tags: readonly string[];
}

export interface QualityRule {
  readonly id: string;
  readonly name: string;
  readonly dimension: string;
  readonly target: string;
  readonly severity: "高" | "中" | "低";
  readonly status: "启用" | "草稿" | "停用";
  readonly passRate: number;
  readonly lastRun: string;
}

export interface IssueTicket {
  readonly id: string;
  readonly title: string;
  readonly object: string;
  readonly priority: "P1" | "P2" | "P3";
  readonly status: "待处理" | "处理中" | "已关闭";
  readonly assignee: string;
  readonly sla: string;
  readonly updatedAt: string;
}

export interface AuditRecord {
  readonly id: string;
  readonly action: string;
  readonly actor: string;
  readonly target: string;
  readonly result: "成功" | "拒绝" | "告警";
  readonly ip: string;
  readonly time: string;
}

