import { useCallback, useEffect, useState } from "react";

const DEFAULT_PATH = "/overview";

function readHashPath(): string {
  const raw = window.location.hash.replace(/^#/, "");
  if (!raw) return DEFAULT_PATH;
  return raw.startsWith("/") ? raw : DEFAULT_PATH;
}

export function useHashPath(): readonly [string, (path: string) => void] {
  const [pathname, setPathname] = useState(readHashPath);

  useEffect(() => {
    const onHashChange = () => setPathname(readHashPath());
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  const navigate = useCallback((path: string) => {
    if (window.location.hash.replace(/^#/, "") !== path) {
      window.location.hash = path;
    }
    setPathname(path);
  }, []);

  useEffect(() => {
    if (!window.location.hash) {
      window.location.hash = DEFAULT_PATH;
    }
  }, []);

  return [pathname, navigate];
}
