function optionsToValueEnum(options, fieldNames = {}) {
    const { value: valueName = 'value', label: labelName = 'label', children: childrenName = 'children' } = fieldNames;
    const valuesMap = new Map();
    const traverse = (items)=>{
        if (!items?.length) return;
        for (const item of items){
            const record = item;
            valuesMap.set(record[valueName], record[labelName]);
            traverse(record[childrenName]);
        }
    };
    traverse(options);
    return valuesMap;
}
export { optionsToValueEnum };
