import {
  AlertOutlined,
  AppstoreOutlined,
  AuditOutlined,
  BellOutlined,
  DatabaseOutlined,
  SafetyCertificateOutlined,
  SettingOutlined,
} from "@ant-design/icons";
import { PageContainer, ProLayout } from "@ant-design/pro-components";
import type { RawHostContext } from "@assistant/context";
import { Avatar, Button, ConfigProvider, Tag, Tooltip, Typography } from "antd";
import { useEffect, useMemo, useState, type ReactNode } from "react";

import {
  productConfig,
  navItems,
  type DemoEntity,
  type DemoNavItem,
} from "./config.js";
import { AuditPage } from "./pages/AuditPage.js";
import { CatalogPage } from "./pages/CatalogPage.js";
import { IssuesPage } from "./pages/IssuesPage.js";
import { OverviewPage } from "./pages/OverviewPage.js";
import { QualityRulesPage } from "./pages/QualityRulesPage.js";
import { useHashPath } from "./useHashPath.js";
import {
  productAHostActions,
  resolveProductAHostNavigation,
} from "./host-actions.js";
import "./app.css";

const { Text, Title } = Typography;
const ASSISTANT_HOST_ACTION_EVENT = "enterprise-assistant:host-action";

interface ModelDisplay {
  readonly label: string;
  readonly badge: string;
  readonly live: boolean;
}

const navIcons: Record<DemoNavItem["key"], ReactNode> = {
  overview: <AppstoreOutlined />,
  catalog: <DatabaseOutlined />,
  "quality-rules": <SafetyCertificateOutlined />,
  issues: <AlertOutlined />,
  audit: <AuditOutlined />,
};

function contextForOverview(entity: DemoEntity): RawHostContext {
  return {
    page: { route: entity.route, title: entity.name, type: "asset-detail" },
    object: { type: entity.kind, rawId: entity.id, name: entity.name },
    business: { domain: "data-governance", module: "quality" },
    hostActions: [...productAHostActions],
    metadata: { demoProduct: productConfig.productCode, environment: "demo" },
  };
}

function contextForNav(nav: DemoNavItem): RawHostContext {
  return {
    page: { route: nav.pageRoute, title: nav.pageTitle, type: nav.pageType },
    business: { domain: "data-governance", module: nav.module },
    hostActions: [...productAHostActions],
    metadata: {
      demoProduct: productConfig.productCode,
      environment: "demo",
      navKey: nav.key,
    },
  };
}

function modelDisplay(value: unknown): ModelDisplay {
  if (typeof value !== "object" || value === null) {
    return { label: "模型状态未知", badge: "AI DEMO", live: false };
  }
  const items = (value as { items?: unknown }).items;
  if (!Array.isArray(items) || items.length === 0) {
    return { label: "模型状态未知", badge: "AI DEMO", live: false };
  }
  const model: unknown = items[0];
  if (typeof model !== "object" || model === null) {
    return { label: "模型状态未知", badge: "AI DEMO", live: false };
  }
  const provider = (model as { provider?: unknown }).provider;
  const modelName = (model as { model?: unknown }).model;
  if (typeof provider !== "string" || typeof modelName !== "string") {
    return { label: "模型状态未知", badge: "AI DEMO", live: false };
  }
  return provider === "deepseek"
    ? { label: `DeepSeek · ${modelName}`, badge: "LIVE DEEPSEEK", live: true }
    : { label: `${provider} · ${modelName}`, badge: "TEST MODEL", live: false };
}

export function App() {
  const [pathname, navigate] = useHashPath();
  const [entityId, setEntityId] = useState<DemoEntity["id"]>(
    productConfig.entities[0].id,
  );
  const [model, setModel] = useState<ModelDisplay>({
    label: "正在连接模型",
    badge: "AI CONNECTING",
    live: false,
  });

  const activeNav =
    navItems.find((item) => item.path === pathname) ?? navItems[0]!;

  const selected =
    productConfig.entities.find((entity) => entity.id === entityId) ??
    productConfig.entities[0];

  const route = useMemo(
    () => ({
      path: "/",
      routes: navItems.map((item) => ({
        path: item.path,
        name: item.label,
        icon: navIcons[item.key],
      })),
    }),
    [],
  );

  useEffect(() => {
    const context =
      activeNav.key === "overview"
        ? contextForOverview(selected)
        : contextForNav(activeNav);
    window.dispatchEvent(
      new CustomEvent("enterprise-assistant:context", { detail: context }),
    );
  }, [activeNav, selected]);

  useEffect(() => {
    const abortController = new AbortController();
    void fetch("/api/v1/models", {
      headers: { authorization: "Bearer mock-token-admin" },
      signal: abortController.signal,
    })
      .then(async (response) => {
        if (!response.ok)
          throw new Error(
            `Model status request failed with ${response.status}.`,
          );
        setModel(modelDisplay(await response.json()));
      })
      .catch((error: unknown) => {
        if (!(error instanceof DOMException && error.name === "AbortError")) {
          setModel({ label: "模型连接失败", badge: "AI ERROR", live: false });
        }
      });
    return () => abortController.abort();
  }, []);

  useEffect(() => {
    const onHostAction = (event: Event) => {
      if (!(event instanceof CustomEvent)) return;
      const allowedRoute = resolveProductAHostNavigation(
        event.detail as unknown,
      );
      if (allowedRoute !== undefined) navigate(allowedRoute);
    };
    window.addEventListener(ASSISTANT_HOST_ACTION_EVENT, onHostAction);
    return () =>
      window.removeEventListener(ASSISTANT_HOST_ACTION_EVENT, onHostAction);
  }, [navigate]);

  const pageBody =
    activeNav.key === "overview" ? (
      <OverviewPage
        selected={selected}
        entityId={entityId}
        onSelectEntity={setEntityId}
      />
    ) : activeNav.key === "catalog" ? (
      <CatalogPage />
    ) : activeNav.key === "quality-rules" ? (
      <QualityRulesPage />
    ) : activeNav.key === "issues" ? (
      <IssuesPage />
    ) : (
      <AuditPage />
    );

  const headerTitle =
    activeNav.key === "overview" ? productConfig.title : activeNav.pageTitle;
  const headerDescription =
    activeNav.key === "overview"
      ? productConfig.description
      : activeNav.description;

  return (
    <ConfigProvider
      theme={{
        token: {
          colorPrimary: "#1677ff",
          borderRadius: 6,
          fontFamily: '"Microsoft YaHei", "PingFang SC", sans-serif',
        },
      }}
    >
      <ProLayout
        title="AURORA CONTROL"
        logo={
          <div className="pro-demo-logo" aria-hidden>
            A
          </div>
        }
        layout="mix"
        fixSiderbar
        location={{ pathname }}
        route={route}
        menuItemRender={(item, dom) => (
          <a
            className="pro-demo-nav-link"
            href={`#${item.path ?? "/overview"}`}
            onClick={(event) => {
              event.preventDefault();
              navigate(item.path ?? "/overview");
            }}
          >
            {dom}
          </a>
        )}
        siderWidth={228}
        contentStyle={{ minHeight: "calc(100vh - 56px)" }}
        actionsRender={() => [
          <Tag key="model" color={model.live ? "success" : "default"}>
            {model.badge}
          </Tag>,
          <Tooltip key="notify" title="系统通知">
            <Button aria-label="通知" type="text" icon={<BellOutlined />} />
          </Tooltip>,
          <Tooltip key="settings" title="全局设置">
            <Button aria-label="设置" type="text" icon={<SettingOutlined />} />
          </Tooltip>,
          <Avatar key="user">马</Avatar>,
        ]}
      >
        <PageContainer
          header={{
            title: (
              <div>
                <Text type="secondary">{productConfig.eyebrow}</Text>
                <Title level={1} style={{ margin: "4px 0 8px" }}>
                  {headerTitle}
                </Title>
                <Text>{headerDescription}</Text>
              </div>
            ),
            breadcrumb: {
              items: [
                { title: "数据治理中心" },
                { title: activeNav.label },
                { title: "华东生产环境" },
              ],
            },
          }}
        >
          {pageBody}
        </PageContainer>
      </ProLayout>
    </ConfigProvider>
  );
}
